using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY") ?? "";
var searchEngineId = Environment.GetEnvironmentVariable("SEARCH_ENGINE_ID") ?? "";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

if (string.IsNullOrWhiteSpace(openAiKey))
{
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// --- Tools ---
var notes = new NoteStore();
var searchTool = new WebSearchTool(searchApiKey, searchEngineId);

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(searchTool.SearchAsync),
    AIFunctionFactory.Create(notes.AddNote),
    AIFunctionFactory.Create(notes.GetNotes),
};

// --- Chat client with tool support ---
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Agent loop ---
Console.WriteLine("Research Agent Ready. Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When given a topic, you:
            1. Search the web for relevant information (make multiple searches if needed).
            2. Take notes on key findings using the note-taking tool.
            3. After gathering enough information, retrieve your notes and provide a well-structured summary.
            Always search first, take notes on important points, then summarize.
            """),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
    };

    Console.WriteLine($"\nResearching: {topic}\n");

    var response = await client.GetResponseAsync(messages, new ChatOptions { Tools = tools });

    Console.WriteLine("=== Research Summary ===\n");
    Console.WriteLine(response.Text);
    Console.WriteLine("\n========================");
}

return 0;

// --- Tool implementations ---

/// <summary>Provides web search functionality via Google Custom Search API.</summary>
sealed class WebSearchTool(string apiKey, string engineId)
{
    private static readonly HttpClient Http = new();

    [Description("Searches the web for information on a given query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        [Description("Number of results to return (max 10)")] int count = 5)
    {
        count = Math.Clamp(count, 1, 10);

        if (string.IsNullOrWhiteSpace(apiKey) || string.IsNullOrWhiteSpace(engineId))
        {
            // Fallback: return a message indicating search is unavailable
            return $"[Web search unavailable - SEARCH_API_KEY/SEARCH_ENGINE_ID not configured. Simulating search for: \"{query}\"]";
        }

        var url = $"https://www.googleapis.com/customsearch/v1?key={apiKey}&cx={engineId}&q={Uri.EscapeDataString(query)}&num={count}";

        try
        {
            var json = await Http.GetFromJsonAsync<JsonElement>(url);
            var items = json.GetProperty("items");
            var results = new List<string>();

            foreach (var item in items.EnumerateArray())
            {
                var title = item.GetProperty("title").GetString();
                var snippet = item.GetProperty("snippet").GetString();
                var link = item.GetProperty("link").GetString();
                results.Add($"- **{title}**\n  {snippet}\n  URL: {link}");
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search error: {ex.Message}";
        }
    }
}

/// <summary>Simple in-memory note store for the agent to record findings.</summary>
sealed class NoteStore
{
    private readonly List<string> _notes = [];

    [Description("Adds a research note. Use this to record key findings from search results.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public void Clear() => _notes.Clear();
}

