+/// <summary>Provides web search functionality via Google Custom Search API.</summary>
+sealed class WebSearchTool(string apiKey, string engineId)
+{
+    private static readonly HttpClient Http = new();
+
+    [Description("Searches the web for information on a given query. Returns a list of results with titles, snippets, and URLs.")]
+    public async Task<string> SearchAsync(
+        [Description("The search query string")] string query,
+        [Description("Number of results to return (max 10)")] int count = 5)
+    {
+        count = Math.Clamp(count, 1, 10);
+
+        if (string.IsNullOrWhiteSpace(apiKey) || string.IsNullOrWhiteSpace(engineId))
+        {
+            // Fallback: return a message indicating search is unavailable
+            return $"[Web search unavailable - SEARCH_API_KEY/SEARCH_ENGINE_ID not configured. Simulating search for: \"{query}\"]";
+        }
+
+        var url = $"https://www.googleapis.com/customsearch/v1?key={apiKey}&cx={engineId}&q={Uri.EscapeDataString(query)}&num={count}";
+
+        try
+        {
+            var json = await Http.GetFromJsonAsync<JsonElement>(url);
+            var items = json.GetProperty("items");
+            var results = new List<string>();
+
+            foreach (var item in items.EnumerateArray())
+            {
+                var title = item.GetProperty("title").GetString();
+                var snippet = item.GetProperty("snippet").GetString();
+                var link = item.GetProperty("link").GetString();
+                results.Add($"- **{title}**\n  {snippet}\n  URL: {link}");
+            }
+
+            return results.Count > 0
+                ? string.Join("\n\n", results)
+                : "No results found.";
+        }
+        catch (Exception ex)
+        {
+            return $"Search error: {ex.Message}";
+        }
+    }
+}
